 "content": "def transform(grid):
    """Expand a central 2 marker into the task's patterned square."""
    n = len(grid[0])
    center = next((i for i, v in enumerate(grid[0]) if v == 2), n // 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            for c in (center-r, center+r):
                if 0 <= c < n:
                    out[r][c] = 2
        for c in range(n):
            if abs(c-center) < r and (c-r) % 4 == 2 and out[r][c] == 0:
                out[r][c] = 1
    return out
